(() => {
  'use strict';
  const el=id=>document.getElementById(id),state={csrf:'',applications:[]};
  const format=value=>value?new Date(String(value).replace(' ','T')+'Z').toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):'—';
  const money=value=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(Number(value)||0);
  async function call(path,method='GET',body){const headers={Accept:'application/json'};if(method!=='GET')headers['X-CSRF-Token']=state.csrf;if(body!==undefined)headers['Content-Type']='application/json';const response=await fetch(path,{method,credentials:'same-origin',cache:'no-store',headers,body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json().catch(()=>({}));if(!response.ok||!data.success)throw Error(data.message||'Event request failed.');return data;}
  function cell(row,text){const td=document.createElement('td');td.textContent=String(text??'—');row.append(td);return td;}
  function show(text,error=false){el('ve-status').textContent=text;el('ve-status').className='vc-status '+(error?'warning':'info');}
  function applications(items){const body=el('ve-applications');body.replaceChildren();if(!items.length){const row=document.createElement('tr');cell(row,'No applications yet. Choose an upcoming event to apply.').colSpan=5;body.append(row);return;}items.forEach(item=>{const row=document.createElement('tr');cell(row,item.title);cell(row,format(item.submitted_at));cell(row,item.status.replaceAll('_',' '));cell(row,Number(item.fee_amount)>0?money(item.fee_amount):'Not due');cell(row,item.payment_status.replaceAll('_',' '));body.append(row);});}
  function upcoming(items){const wrap=el('ve-upcoming');wrap.replaceChildren();const applied=new Set(state.applications.map(item=>item.event_id));if(!items.length){const p=document.createElement('p');p.textContent='No published upcoming events are available right now.';wrap.append(p);return;}items.forEach(item=>{const card=document.createElement('article');card.className='vc-card';const body=document.createElement('div');body.className='vc-card-body';const title=document.createElement('h3');title.textContent=item.title;const detail=document.createElement('p');detail.textContent=[format(item.starts_at),item.venue_name||item.venue_type,item.host_name].filter(Boolean).join(' · ');const description=document.createElement('p');description.textContent=item.short_description||'';const button=document.createElement('button');button.type='button';button.className='vc-btn primary mt-3';button.textContent=applied.has(item.id)?'Already applied':'Apply';button.disabled=applied.has(item.id);button.addEventListener('click',()=>{el('ve-form').reset();el('ve-form').elements.namedItem('event_id').value=item.id;el('ve-title').textContent='Apply to '+item.title;el('ve-dialog').showModal();});body.append(title,detail,description,button);card.append(body);wrap.append(card);});}
  async function load(){try{const [identity,own,publicEvents]=await Promise.all([call('../../../api/vendor/auth/me.php'),call('../../../api/vendor/event-applications.php'),call('../../../api/public/events.php')]);state.csrf=identity.csrf_token||'';state.applications=own.applications||[];applications(state.applications);upcoming(publicEvents.events||[]);show(state.applications.length+' applications · '+(publicEvents.events||[]).length+' upcoming events');}catch(error){show(error.message,true);}}
  el('ve-close').addEventListener('click',()=>el('ve-dialog').close());
  el('ve-form').addEventListener('submit',async event=>{event.preventDefault();if(!event.currentTarget.reportValidity())return;const button=event.submitter;button.disabled=true;try{const data=Object.fromEntries(new FormData(event.currentTarget));await call('../../../api/vendor/event-applications.php','POST',data);el('ve-dialog').close();await load();}catch(error){show(error.message,true);}finally{button.disabled=false;}});
  load();
})();
